<?php
namespace OpenBKAdmin\Helper;
use GuzzleHttp\Client;
class OpenBekenOtaScraper{public const RELEASES_URL='https://github.com/openshwprojects/OpenBK7231T_App/releases';private const API_URL='https://api.github.com/repos/openshwprojects/OpenBK7231T_App/releases';private const CACHE_TTL=900;private string$updateChannel;private Client$client;private?array$releaseCache=null;public function __construct(string$updateChannel,$client=null){$this->updateChannel=$updateChannel;$this->client=$client instanceof Client?$client:new Client(['headers'=>['Accept'=>'application/vnd.github+json','User-Agent'=>'OpenBKAdmin'],'connect_timeout'=>10,'timeout'=>20]);}public function getRecentReleases(int$limit=10):array{$limit=max(1,min(20,$limit));try{$data=json_decode((string)$this->client->get(self::API_URL.'?per_page='.$limit)->getBody(),true,512,JSON_THROW_ON_ERROR);$out=[];foreach($data as$r){if(!empty($r['draft']))continue;$out[]=['version'=>(string)($r['tag_name']??$r['name']??''),'published_at'=>(string)($r['published_at']??''),'prerelease'=>!empty($r['prerelease'])];if(count($out)>=$limit)break;}return$out;}catch(\Throwable$e){return[];}}public function getOtaFirmwares(?string$version=null):array{$release=$this->getRelease($version);$tag=(string)($release['tag_name']??'');$publishedAt=new \DateTime((string)($release['published_at']??'now'));$assets=[];foreach(($release['assets']??[])as$a){$n=(string)($a['name']??'');$u=(string)($a['browser_download_url']??'');if($n!==''&&$u!=='')$assets[$n]=$u;}$result=[];foreach($this->parseOtaTable((string)($release['body']??''))as$p=>$f){$u=$assets[$f]??null;if($u===null)foreach($assets as$an=>$au)if(strcasecmp($an,$f)===0){$f=$an;$u=$au;break;}if($u!==null)$result[$p]=['platform'=>$p,'filename'=>$f,'url'=>$u,'version'=>$this->extractVersion($f,$tag),'publishedAt'=>$publishedAt];}if(empty($result))foreach($assets as$f=>$u){if(!preg_match('/^Open([A-Za-z0-9]+)_(\d+\.\d+\.\d+)(?:\.rbl|_ota\.img|_OTA\.bin(?:\.xz\.ota)?|_gz\.img)$/i',$f,$m))continue;$p=strtoupper($m[1]);$result[$p]=['platform'=>$p,'filename'=>$f,'url'=>$u,'version'=>$m[2],'publishedAt'=>$publishedAt];}ksort($result,SORT_NATURAL|SORT_FLAG_CASE);return$result;}public function getOtaFirmware(string$p,?string$v=null):array{$p=strtoupper(trim($p));$f=$this->getOtaFirmwares($v);if(!isset($f[$p]))throw new \InvalidArgumentException(sprintf('No OTA Update asset is published for chipset %s.',$p));return$f[$p];}private function getRelease(?string$version=null):array{if($version!==null&&$version!==''&&$version!=='latest'){try{return json_decode((string)$this->client->get(self::API_URL.'/tags/'.rawurlencode($version))->getBody(),true,512,JSON_THROW_ON_ERROR);}catch(\Throwable$e){throw new \RuntimeException('Unable to read OpenBeken release '.$version.'. '.$e->getMessage(),0,$e);}}if($this->releaseCache!==null)return$this->releaseCache;$url=self::API_URL.($this->updateChannel==='dev'?'?per_page=20':'/latest');$data=json_decode((string)$this->client->get($url)->getBody(),true,512,JSON_THROW_ON_ERROR);if($this->updateChannel==='dev'){foreach($data as$r)if(empty($r['draft']))return$this->releaseCache=$r;throw new \RuntimeException('No OpenBeken GitHub release is available.');}return$this->releaseCache=$data;}private function parseOtaTable(string$b):array{$rows=[];foreach(preg_split('/\R/',$b)as$l){if(!str_contains($l,'|'))continue;$c=array_map('trim',explode('|',trim($l," \t|")));if(count($c)<3||strcasecmp(trim(preg_replace('/[`*_]/','',$c[1])),'OTA Update')!==0)continue;$p=strtoupper(trim(preg_replace('/[`*_]/','',$c[0])));$f=trim($c[2]);if(preg_match('/\[([^\]]+)\]\([^\)]+\)/',$f,$m))$f=$m[1];$f=trim(preg_replace('/[`*_]/','',$f));if($p!==''&&$f!=='')$rows[$p]=$f;}return$rows;}private function extractVersion(string$f,string$t):string{if(preg_match('/(?<!\d)(\d+\.\d+\.\d+(?:\.\d+)?)(?!\d)/',$f,$m))return$m[1];return ltrim($t,'vV');}}
